// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up a target contract that will receive ether and trigger the fallback
        // We use address(0xdead) as a simple target; it has no receive or fallback,
        // so the call will fail? Actually we need a target that accepts ether to trigger fallback.
        // Let's deploy a minimal contract with a payable fallback from the test helper.
        // We'll use a simple address that is a contract with a payable fallback.
        // To avoid extra contracts, we can send to address(this) which is the test contract;
        // test contract has a receive function (from Test) but we can use vm.prank.
        // Simpler: send to the test contract itself, which has a receive() external payable {} inherited from Test.
        address target = address(this);
        // Fund the contract owner
        vm.deal(address(this), 1 ether);
        // Owner is msg.sender of deployment, which is this test contract?
        // Actually new C() sets owner = msg.sender which is this test contract.
        vm.prank(address(this));
        c.sendMoney(target, 1 wei);
        // After transfer, the reference's fallback was called on target (test contract receives ether and increments depositsCount)
        // The test contract's receive does not affect C's state; but the fallback of target is irrelevant.
        // Wait: the change is in C's fallback, not target's. The sendMoney calls target, not C itself.
        // So target receiving ether does not call C's fallback. So depositsCount never changes.
        // I misread: The fallback in C is triggered when C receives ether directly (msg.sender sends to C).
        // sendMoney sends ether from C to _target; that does not call C's fallback.
        // So the difference cannot be triggered via sendMoney alone.
        // Re-read: "after a call to sendMoney(...) completes, the value of state variable depositsCount differs"
        // That suggests sendMoney somehow causes C to receive ether (via reentrancy?).
        // Possibly the target is C itself? If _target == address(c), then sending ether back to C triggers its fallback.
        // Yes! If we call sendMoney with _target = address(c), then C sends ether to itself, which triggers its own fallback.
        // So use target = address(c).
        address target2 = address(c);
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        c.sendMoney(target2, 1 wei);
        // Now, before sendMoney, depositsCount = 0. The sendMoney sends 1 wei to C itself.
        // The fallback executes (in reference) incrementing depositsCount to 1.
        // In mutant, depositsCount stays 0.
        // After sendMoney completes, check c.depositsCount().
        assertTrue(c.depositsCount() == 1);
    }
}

