pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up a target address with no receive/fallback (the Test contract itself has no fallback)
        address target = address(0x1234);
        // Ensure reference can call sendMoney with non-zero value – but here we test with _value=1
        // The buggy version sends 0 value, which fails on transfer to address without fallback,
        // but the buggy code doesn't require the return value, so it succeeds.
        // Reference requires the call to succeed, so it reverts when sending 0 to a contract with no fallback.
        // To see divergence: after calling sendMoney(0x1234, 1), reference reverts, buggy doesn't.
        // But we need a concrete assertion on state. The difference is: after a successful call to sendMoney,
        // the buggy contract's owner (the test contract) still has ether not sent; reference reverts.
        // We'll capture whether the call reverts.

        vm.deal(address(this), 1 ether); // Not needed, but for completeness
        vm.prank(address(this)); // Only owner can call sendMoney; owner is msg.sender in constructor = address(this)

        bool ok;
        try c.sendMoney{value: 1}(target, 1) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference contract reverts because it sends 1 wei (not 0) to an address without fallback
        // Actually, wait: the mutant sends value 0; the reference sends _value (1). 
        // But the difference described: change is "Replace call with a plain transfer without the require check and without forwarding the value."
        // So the mutant's call sends value 0, while reference sends _value. 
        // Sending 0 wei to a contract without receive/fallback succeeds (no value transferred but call returns true).
        // Actually, sending 0 wei to a contract with no receive/fallback returns true in Solidity >=0.8? 
        // The call will still execute the fallback if exists, but if no fallback, the call reverts internally? 
        // No: sending 0 wei via call to an address with no code succeeds (returns true). 
        // To make a difference, we need a contract that rejects calls? Simpler: use an address with code that has no receive/fallback.
        // Deploy a tiny contract that has receive but reverts? 
        // Better approach: use address(this) as target, which has no fallback but is a contract. 
        // Actually address(this) has no payable fallback, so sending value >0 via call will revert, 
        // but sending 0 wei will succeed because no data, no value? The EVM: if no receive and no fallback, 
        // a call with value >0 reverts; call with value 0 and no data returns true (no code execution).
        // So the reference sending 1 wei will revert when called on this contract (no receive). 
        // The mutant sending 0 wei will succeed.
        // That's the divergence: reference reverts, mutant returns.

        // So we assert that ok == false for the reference? Actually the test must fail on buggy.
        // The test should pass on reference (meaning ok == false, since reference reverts) and fail on buggy (ok == true).
        // But the requirement: assertion that reference holds and bug breaks. 
        // If we assert ok == false, reference holds, buggy returns true so assertion fails. That's correct.

        assertTrue(!ok, "sendMoney to address without receive should revert");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a contract that always reverts on receive/fallback
        RevertingTarget target = new RevertingTarget();
        // Fund the contract with some ether
        vm.deal(address(c), 10 ether);
        // Call sendMoney to the reverting target with a non-zero value
        bool ok;
        try c.sendMoney(address(target), 1) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: transaction reverts, ok == false
        // Bug: transaction succeeds, ok == true
        assertTrue(ok, "sendMoney should have reverted on reference, but bug allows it to succeed");
    }
}

contract RevertingTarget {
    fallback() external payable {
        revert("I always revert");
    }
    receive() external payable {
        revert("I always revert");
    }
}

